     case s.decodedResult of {Right _ -> pure (); Left e -> fail (Text.unpack e)}
     ) eligible
   text ("fulfilled=" <> Text.pack (show (length results)) <> "\nskipped=" <> Text.pack (show (length orders - length eligible)))

