do
  r <- Tools.read_file Tools.ToolArguments_read_file { Tools.path = "numbers.csv" }
  s <- either (fail . Text.unpack) pure r.decodedResult
  let ns = map (read . Text.unpack) $ filter (not . Text.null) $ Text.split (\c -> c == ',' || c == '\n' || c == '\r' || c == ' ' || c == '\t') s :: [Integer]
  let n = length ns
  let total = sum ns
  let hundredths = (abs total * 200 + fromIntegral n) `div` (2 * fromIntegral n)
  let meanStr = (if total < 0 then "-" else "") ++ show (hundredths `div` 100) ++ "." ++ (if hundredths `mod` 100 < 10 then "0" else "") ++ show (hundredths `mod` 100)
  text $ Text.pack $ "count=" ++ show n ++ "\nsum=" ++ show total ++ "\nminimum=" ++ show (minimum ns) ++ "\nmaximum=" ++ show (maximum ns) ++ "\nmean=" ++ meanStr
